pub const PackageInstallMethod = enum(u8) {
    clonefile,
    clonefile_each_dir,
    hardlink,
    copyfile,
    symlink,
    pub fn get(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn has(__cp_s: []const u8) bool { return std.meta.stringToEnum(@This(), __cp_s) != null; }
